This function checks if the input `n` is less than or equal to 0 and returns an empty list if true. Otherwise, it iterates through numbers 1 to `n`, appending 'Fizz', 'Buzz', 'FizzBuzz', or the number itself to the result list based on the conditions provided.

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True
